\begin{align}
\label{cor5.2i} \sum_{m\leq M}\min \bigg(\dfrac{X}{m}+1,\dfrac{1}{\|m\theta\|}\bigg)
 &\ll  X\bigg(\dfrac{M}{X} + q\lvert\beta\rvert + \dfrac{1}{Xq\lvert\beta\rvert}\bigg)(\log 2qM)^2.
\end{align}

\begin{align}
\label{cor5.2ii} \sum_{m\leq M}\bigg(\dfrac{X}{m} + 1, \dfrac{1}{\|m\theta\|}\bigg) \ll X\bigg(\dfrac{M}{X} + \dfrac{1}{q} + \dfrac{q}{X}\bigg)(\log 2qM).
\end{align}

\begin{align}\label{cor5.2iii}
\sum_{m\leq M}\bigg(\dfrac{X}{m} + 1, \dfrac{1}{\|m\theta\|}\bigg) \ll X\bigg\{\dfrac{M}{X} + \min\bigg(q|\beta| + \dfrac{1}{Xq|\beta|}, \dfrac{1}{q} + \dfrac{q}{X}\bigg)\bigg\}(\log 2qM)^2.
\end{align}

\begin{align}\label{cor5.2iv}
\min\bigg(\dfrac{1}{q}, \dfrac{1}{Xq|\beta|}\bigg)\leq \dfrac{2}{q(1+|\beta|X)}.
\end{align}

\begin{align}\notag 
\min\bigg(q|\beta| + \dfrac{1}{Xq|\beta|}, \dfrac{1}{q} + \dfrac{q}{X}\bigg)\ll q|\beta| + \dfrac{q}{X} + \dfrac{1}{q(1+|\beta|X)} = \dfrac{qH}{X} + \dfrac{1}{qH},
\end{align}

\label{bilinear lemma}
Let $M, N \geq 1$ be such that $MN\leq X$. Let $\theta = a/q + \beta$ for some $(a, q)=1$ and $|\beta| < 1/q^2$. Suppose ${\alpha}_1$ and ${\alpha}_2$ are two arithmetic functions supported in $[1, M]$ and $[1, N]$, respectively. Then we have
\begin{align}\notag
\sum_{n\leq X}({\alpha}
_1*{\alpha}_2)(n)e(n \theta) \ll X^{1/2}\lVert {\alpha}_1 \rVert_2 \lVert {\alpha}_2 \rVert_2\bigg(\dfrac{M}{X} + \dfrac{N}{X} + \dfrac{qH}{X} + \dfrac{1}{qH} \bigg)^{1/2}(\log 2qX),
\end{align}
where $H=1+|\beta|X$.

\begin{align}\notag
\sum_{n\leq X}({\alpha}
_1*{\alpha}_2)(n)e(n \theta) \ll X^{1/2}\lVert {\alpha}_1 \rVert_2 \lVert {\alpha}_2 \rVert_2\bigg(\dfrac{M}{X} + \dfrac{N}{X} + \dfrac{qH}{X} + \dfrac{1}{qH} \bigg)^{1/2}(\log 2qX),
\end{align}

\label{Mikawa}
Let $M, N\geq 1$ be such that $M, N\leq X$. Let $\theta= a/q + \beta$ with $(a, q)=1$, $|\beta\rvert <1/q^2$ and $q<X$. Then for any $\psi>0$, one has
\begin{align}
\notag M\sum_{m\sim M}\sum_{n\sim N}\uptau_3(n)\min\bigg(\dfrac{X}{m^2n} + 1, \dfrac{1}{\lVert m^2n \theta \rVert}\bigg)\ll &~M^2N(\log X)^3\\
\notag & + X\bigg(\dfrac{1}{M} + \dfrac{qH}{X} + \dfrac{1}{qH}\bigg)^{1/2-\psi}(\log X)^8,
\end{align}
where $H=1+|\beta|X$.

\begin{align}
\notag M\sum_{m\sim M}\sum_{n\sim N}\uptau_3(n)\min\bigg(\dfrac{X}{m^2n} + 1, \dfrac{1}{\lVert m^2n \theta \rVert}\bigg)\ll &~M^2N(\log X)^3\\
\notag & + X\bigg(\dfrac{1}{M} + \dfrac{qH}{X} + \dfrac{1}{qH}\bigg)^{1/2-\psi}(\log X)^8,
\end{align}

\label{lemmatype1}
Let $v>0$. Let $D, M\geq 1$ be such that $DM<X$. Let $\theta=a/q+\beta$ with $(a, q)=1$, $\lvert \beta \rvert <1/q^2$ and $q<X$. Suppose ${\alpha}$ is an arithmetic function supported in $[1, M]$ and satisfies $\lvert {\alpha}\rvert \leq \uptau_{h_1}\cdot \log^{h_2}$ for some fixed integers $h_1\geq 1, h_2\geq 0$. Furthermore, let $h_3\geq 1$ be a fixed integer. Then, we have
\begin{align}
\notag \sum_{\substack{d\leq D}}\uptau_{h_3}(d)\cdot\max_{(c,d)=1}&\bigg\lvert \sum_{\substack{mn <X\\1\leq m\leq M\\mn\equiv c\imod d}}{\alpha}(m)(\log n)^ve(mn\theta)\bigg\rvert\\
\notag &\ll X\bigg(\dfrac{DM}{X} + \dfrac{qH}{X} + \dfrac{1}{qH}\bigg)^{1/2}(\log X)^{(h_1+h_3)^2/2 + h_2+v + 1},
\end{align}
where $H=1+|\beta|X$.

\begin{align}
\notag \sum_{\substack{d\leq D}}\uptau_{h_3}(d)\cdot\max_{(c,d)=1}&\bigg\lvert \sum_{\substack{mn <X\\1\leq m\leq M\\mn\equiv c\imod d}}{\alpha}(m)(\log n)^ve(mn\theta)\bigg\rvert\\
\notag &\ll X\bigg(\dfrac{DM}{X} + \dfrac{qH}{X} + \dfrac{1}{qH}\bigg)^{1/2}(\log X)^{(h_1+h_3)^2/2 + h_2+v + 1},
\end{align}

Let $\mathcal{S}_{\textup{Type I}}$ be the sum that we wish to estimate. Applying partial summation and then using the fact that $\sum_{n\leq y}e(nt) \ll \min(y, \|t\|^{-1})$ for any real numbers $y>1$ and $t$, we have
\begin{align}
\notag \sum_{\substack{n< X/m\\n\equiv c\overline{m}\imod {d}}}(\log n)^ve(mn\theta)  &\ll (\log X/m)^v \min\bigg(\dfrac{X}{dm} + 1, \dfrac{1}{\|dm\theta\|}\bigg).
\end{align}
This implies that
\begin{align}
\notag |\mathcal{S}_{\textup{Type I}}|&\ll(\log X)^{v} \sum_{d\leq D}\uptau_{h_3}(d)\sum_{\substack{m\leq M}}|{\alpha}(m)|\min\bigg(\dfrac{X}{dm} + 1, \dfrac{1}{\lVert dm\theta\rVert}\bigg),
\end{align}
Next, we write $d^\prime =dm$, so that $d^\prime \leq DM$. Then, by the Cauchy-Schwarz inequality and Corollary \ref{Corollary1} along with the fact that $|{\alpha}| \leq \uptau_{h_1}\cdot \log^{h_2}$, we have
\begin{align}
\notag |\mathcal{S}_{\textup{Type I}}|   & \ll(\log X)^{v+h_2}\bigg(X\sum_{d^\prime \leq DM}\dfrac{\uptau_{h_1+h_3}(d^\prime)^2}{d^\prime}\bigg)^{1/2}\cdot \bigg(\sum_{d^\prime \leq DM}\min\bigg(\dfrac{X}{d^\prime} + 1, \dfrac{1}{\lVert d^\prime \theta\rVert}\bigg)\bigg)^{1/2}\\
\notag & \ll (\log X)^{v+h_2} X(\log X)^{(h_1+h_3)^2/2}\bigg(\dfrac{DM}{X}+ \dfrac{qH}{X} + \dfrac{1}{qH}\bigg)^{1/2}(\log X),
\end{align}
where we have used the fact that $\sum_{n\leq y}\uptau_h(n)^2/n \ll (\log y)^{h^2}$ for any real number $y\geq 2$ and for any integer $h\geq 1$. The above estimate on simplification yields the desired result.

\begin{align}
\notag \sum_{\substack{n< X/m\\n\equiv c\overline{m}\imod {d}}}(\log n)^ve(mn\theta)  &\ll (\log X/m)^v \min\bigg(\dfrac{X}{dm} + 1, \dfrac{1}{\|dm\theta\|}\bigg).
\end{align}

\begin{align}
\notag |\mathcal{S}_{\textup{Type I}}|&\ll(\log X)^{v} \sum_{d\leq D}\uptau_{h_3}(d)\sum_{\substack{m\leq M}}|{\alpha}(m)|\min\bigg(\dfrac{X}{dm} + 1, \dfrac{1}{\lVert dm\theta\rVert}\bigg),
\end{align}

\begin{align}
\notag |\mathcal{S}_{\textup{Type I}}|   & \ll(\log X)^{v+h_2}\bigg(X\sum_{d^\prime \leq DM}\dfrac{\uptau_{h_1+h_3}(d^\prime)^2}{d^\prime}\bigg)^{1/2}\cdot \bigg(\sum_{d^\prime \leq DM}\min\bigg(\dfrac{X}{d^\prime} + 1, \dfrac{1}{\lVert d^\prime \theta\rVert}\bigg)\bigg)^{1/2}\\
\notag & \ll (\log X)^{v+h_2} X(\log X)^{(h_1+h_3)^2/2}\bigg(\dfrac{DM}{X}+ \dfrac{qH}{X} + \dfrac{1}{qH}\bigg)^{1/2}(\log X),
\end{align}

\label{lemmatypeIIpointwise}
Let $M, N\geq 1$ be such that $MN\leq X$. Let $\theta=a/q+\beta$ with $(a, q)=1$, $\lvert \beta \rvert <1/q^2$ and $q<X$. Suppose ${\alpha}_1$ and ${\alpha}_2$ are two arithmetic functions supported in $[M, 2M]$ and $[N, 2N]$, respectively, and satisfy $|{\alpha}_1|, |{\alpha}_2| \leq \uptau_h\cdot \log $  for some fixed integer $h\geq 1$. Let $c$ and $d$ be non-zero positive integers such that $(c, d)=1$. Then, we have
\begin{align}\label{eq: pointwise}
\bigg\lvert\sum_{\substack{mn <X\\m\sim M, n\sim N\\mn\equiv c\imod d}}{\alpha}_1(m){\alpha}_2(n)e(mn\theta)\bigg\rvert\ll X\bigg(\dfrac{M}{X}+\dfrac{N}{X}+\dfrac{qH}{X} + \dfrac{1}{qH}\bigg)^{1/2}(\log X)^{h^2 + 2},
\end{align}
where $H=1+|\beta|X$.

\begin{align}\label{eq: pointwise}
\bigg\lvert\sum_{\substack{mn <X\\m\sim M, n\sim N\\mn\equiv c\imod d}}{\alpha}_1(m){\alpha}_2(n)e(mn\theta)\bigg\rvert\ll X\bigg(\dfrac{M}{X}+\dfrac{N}{X}+\dfrac{qH}{X} + \dfrac{1}{qH}\bigg)^{1/2}(\log X)^{h^2 + 2},
\end{align}

Let $\chi$ be Dirichlet character modulo $d$. Then, by the orthogonality of Dirichlet characters, we bound the sum in the left-hand side of \eqref{eq: pointwise} as
\begin{align}
\notag &\leq \dfrac{1}{\varphi(d)}\sum_{\chi\imod d}\bigg\lvert\sum_{\substack{mn <X\\m\sim M, n\sim N}}{\alpha}_1(m)\chi(m){\alpha}_2(n)\chi(n)e(mn\theta)\bigg \rvert.
\end{align}
Now we use Lemma \ref{bilinear lemma} with ${\alpha}_1\cdot \chi$ and ${\alpha}_2\cdot \chi$ to estimate the sum over $mn <X$  and the trivial bound to sum over $\varphi(d)$ characters modulo $\chi$ to show that the above sum is
\begin{align}
\label{lemmapeq1} &\ll X^{1/2}\lVert{\alpha}_1\rVert_2\lVert {\alpha}_2\rVert_2\bigg(\dfrac{M}{X} + \dfrac{N}{X} + \dfrac{qH}{X} + \dfrac{1}{qH}\bigg)^{1/2}(\log qX).
\end{align}
Next, we recall that $|{\alpha}_1|, |{\alpha}_2|\leq \uptau_h \cdot \log $ to obtain
\begin{align}
\label{lemmapeq2}\lVert{\alpha}_1\rVert_2\lVert{\alpha}_2\rVert_2 \leq \bigg(\sum_{m\sim M}\uptau_h(m)^2\bigg)^{1/2}\bigg(\sum_{n\sim N}\uptau_h(n)^2\bigg)^{1/2}(\log X)^2 \ll (MN)^{1/2}(\log X)^{h^2+1},
\end{align}
using the fact that $\sum_{n< y}\uptau_h(n)^2 \ll y(\log y)^{h^2-1}$ for any real number $y\geq 2$.
Substituting the estimate from \eqref{lemmapeq2} in \eqref{lemmapeq1} and using the fact that $MN\leq X$ and $q< X$ completes the proof of the lemma.

\begin{align}
\notag &\leq \dfrac{1}{\varphi(d)}\sum_{\chi\imod d}\bigg\lvert\sum_{\substack{mn <X\\m\sim M, n\sim N}}{\alpha}_1(m)\chi(m){\alpha}_2(n)\chi(n)e(mn\theta)\bigg \rvert.
\end{align}

\begin{align}
\label{lemmapeq1} &\ll X^{1/2}\lVert{\alpha}_1\rVert_2\lVert {\alpha}_2\rVert_2\bigg(\dfrac{M}{X} + \dfrac{N}{X} + \dfrac{qH}{X} + \dfrac{1}{qH}\bigg)^{1/2}(\log qX).
\end{align}

\begin{align}
\label{lemmapeq2}\lVert{\alpha}_1\rVert_2\lVert{\alpha}_2\rVert_2 \leq \bigg(\sum_{m\sim M}\uptau_h(m)^2\bigg)^{1/2}\bigg(\sum_{n\sim N}\uptau_h(n)^2\bigg)^{1/2}(\log X)^2 \ll (MN)^{1/2}(\log X)^{h^2+1},
\end{align}

\label{lemmatypeII}
Let $c$ be a fixed non-zero integer. Let $D_1, D_2, M, N \geq 1$ be such that
\[MN< X, \quad D_1M< X \quad  \text{and} \quad D_1D_2^{2}N< X.\]
 Let $\theta=a/q+\beta$ with $(a, q)=1$, $\lvert \beta \rvert <1/q^2$ and $q<X$. Suppose ${\alpha}_1$ and ${\alpha}_2$ are two arithmetic functions with support $[M, 2M]$ and $[N, 2N]$, respectively, and satisfy $\lvert {\alpha}_1|, |{\alpha}_2| \leq \uptau_h\cdot \log $ for some fixed integer $h\geq 1$. Then, for any integer $h_1\geq 1$, we have
\begin{align}
\notag &\mathop{\sum\sum}_{\substack{d_1\sim D_1\\d_2\sim D_2\\(cd_1,d_2)=1}}\uptau_{h_1}(d_1)\max_{(c', d_1)=1}\Bigg\lvert\sum_{\substack{mn <X\\m\sim M, n\sim N\\mn\equiv c'\imod {d_1}\\mn\equiv c\imod {d_2}}}{\alpha}_1(m){\alpha}_2(n)e(mn\theta)\Bigg\rvert\\
\notag &\ll  X\bigg(\dfrac{D_1M}{X} + \dfrac{(D_1D_2)^2}{X}+\dfrac{D_1D_2^2N}{X} + \dfrac{1}{D_1^{1/4}} + \dfrac{(qH)^{1/4}}{X^{1/4}} + \dfrac{1}{(qH)^{1/4}}\bigg)^{1/2}(\log X)^{h^2+h_1^2/2 + 5},
\end{align}
where $H=1+|\beta|X$.

\begin{align}
\notag &\mathop{\sum\sum}_{\substack{d_1\sim D_1\\d_2\sim D_2\\(cd_1,d_2)=1}}\uptau_{h_1}(d_1)\max_{(c', d_1)=1}\Bigg\lvert\sum_{\substack{mn <X\\m\sim M, n\sim N\\mn\equiv c'\imod {d_1}\\mn\equiv c\imod {d_2}}}{\alpha}_1(m){\alpha}_2(n)e(mn\theta)\Bigg\rvert\\
\notag &\ll  X\bigg(\dfrac{D_1M}{X} + \dfrac{(D_1D_2)^2}{X}+\dfrac{D_1D_2^2N}{X} + \dfrac{1}{D_1^{1/4}} + \dfrac{(qH)^{1/4}}{X^{1/4}} + \dfrac{1}{(qH)^{1/4}}\bigg)^{1/2}(\log X)^{h^2+h_1^2/2 + 5},
\end{align}

The proof of the lemma is closely related to the proofs of \cite[Proposition 9]{Mat} and \cite[Theorem (p.~352)]{Mik}, but for the convenience of the reader we include the proof here.
We will estimate the sum:
\begin{align}\notag 
\mathcal{S}_{\text{Type II}}:=\mathop{\sum\sum}_{\substack{d_1\sim D_1\\d_2\sim D_2\\(cd_1,d_2)=1}}\uptau_{h_1}(d_1)\max_{(c', d_1)=1}&\Bigg\lvert\sum_{\substack{mn <X\\m\sim M, n\sim N\\mn\equiv c'\imod {d_1}\\mn\equiv c\imod {d_2}}}{\alpha}_1(m){\alpha}_2(n)e(mn\theta)\Bigg\rvert.
\end{align}
Let us assume that the maximum over $c'$ is attained at $c_{d_1}$. Let ${\lambda}(d_1, d_2)\in \mathbb{C}$ be of absolute value $1$  whenever $c'=c_{d_1}$ and $(d_1, c_{d_1})=(d_1, d_2)=(d_2, c)=1$  for $d_1\sim D_1$ and $d_2\sim D_2$. Then, we have
\begin{align}
\notag \mathcal{S}_{\text{Type II}}=\sum_{d_1\sim D_1}\uptau_{h_1}(d_1)\sum_{m\sim M}{\alpha}_1(m)\sum_{d_2\sim D_2}{\lambda}(d_1, d_2)\sum_{\substack{mn <X\\n\sim N\\mn\equiv c_{d_1}\imod {d_1}\\mn\equiv c\imod {d_2}}}{\alpha}_2(n)e(mn\theta).
\end{align}
We apply the Cauchy-Schwarz inequality to obtain
\begin{align}
\notag |\mathcal{S}_{\text{Type II}}|^2\leq &~D_1 (\log X)^{h_1^2-1}\|{\alpha}_1\|_2^2\sum_{\substack{d_1\sim D_1}}\sum_{\substack{m\sim M}}\bigg|\sum_{\substack{d_2\sim D_2}}{\lambda}(d_1,d_2)\sum_{\substack{n<X/m\\ n\sim N\\ mn\equiv c_{d_1} \imod {d_1}\\mn\equiv c\imod {d_2}}}{\alpha}_2(n)e(mn\theta)\bigg|^2\\
\notag \ll &~ D_1(\log X)^{h_1^2-1}\|{\alpha}_1\|_2^2\sum_{d_1\sim D_1}\sum_{\substack{d_2, d_2'\sim D_2\\(d_2d_2', d_1)=1}}\sum_{\substack{n_1, n_2\sim N\\(n_1, d_1d_2)=(n_2, d_1d_2')=1 }}\big|{\alpha}_2(n_1)\overline{{\alpha}_2(n_2)}\big|\\
\notag &\times \Bigg|\sum_{\substack{m\sim M\\m< \min (X/n_1, X/n_2)\\mn_1\equiv mn_2\equiv c_{d_1}\imod {d_1}\\mn_1\equiv c\imod {d_2}\\mn_2\equiv c\imod {d_2'}}}e\big(m(n_1-n_2)\theta\big)\Bigg|\\
\notag \ll &~ D_1(\log X)^{h_1^2-1}\|{\alpha}_1\|_2^2\sum_{d_1\sim D_1}\sum_{\substack{d_2, d_2'\sim D_2\\(d_2d_2', d_1)=1}}\sum_{j\in \{1, 2\}}\sum_{\substack{n_1, n_2\sim N\\(n_1, d_1d_2)=(n_2, d_1d_2')=1 }}\big|{\alpha}_2(n_j)|^2\\
\notag &\times \Bigg|\sum_{\substack{m\sim M\\m< \min (X/n_1, X/n_2)\\mn_1\equiv mn_2\equiv c_{d_1}\imod {d_1}\\mn_1\equiv c\imod {d_2}\\mn_2\equiv c\imod {d_2'}}}e\big(m(n_1-n_2)\theta\big)\Bigg|
\end{align}
using the fact $|{\alpha}_2(n_1)\overline{{\alpha}_2(n_2)}|\leq |{\alpha}_2(n_1)|^2 + |{\alpha}_2(n_2)|^2$. 

The above congruences $mn_1 \equiv mn_2 \equiv c_{d_1} \imod {d_1}$, $mn_1\equiv c \imod {d_2}$, and $mn_1\equiv c\imod {d_2'}$ have a solution in $m$ if and only if $(n_1, d_1d_2)=(n_2, d_1d_2')=1$ and $n_1 \equiv n_2\imod {d_1 (d_2, d_2')}$. Then, we have a unique solution $m\equiv h'\imod {d_1[d_2, d_2']}$ for some $h'\in \{0, 1, \dotsc, d_1[d_2, d_2']-1\} $. Next, we write 
\[n_1-n_2=n'd_1(d_2, d_2') \quad \text{and}\quad  m=h'+ m'd_1[d_2, d_2']\]
so that $|n'|< 4N/d_1(d_2, d_2')$ and $m'\ll 1+M/d_1[d_2, d_2']$. This implies that
\begin{align}
\notag m(n_1-n_2)=h'n'd_1(d_2, d_2') + d_1^2d_2d_2'n'm'. 
\end{align}
Then, we have
 \begin{align}
 \notag \lvert\mathcal{S}_{\textup{Type II}}\rvert^2 \ll &~D_1(\log X)^{h_1^2-1}\lVert {\alpha}_1\rVert_2^2 \sum_{\substack{d_1\sim D_1}}\sum_{\substack{d_2, d_2^\prime \sim D_2\\(d_2d_2^\prime, d_1)=1}} \sum_{n_1\sim N}|{\alpha}_2(n_1)|^2\\\notag &\times \sum_{|n^\prime|< 4N/d_1(d_2, d_2^\prime)}\bigg|\sum_{m^\prime}e(m^\prime n^\prime d_1^2d_2d_2^\prime \theta)\bigg|\\
\notag \ll &~D_1(\log X)^{h_1^2-1}\lVert {\alpha}_1\rVert_2^2\lVert {\alpha}_2 \rVert_2^2\\
\label{meth2i}  &\times \sum_{\substack{d_1\sim D_1}}\sum_{\substack{d_2, d_2^\prime \sim D_2\\(d_2d_2^\prime,d_1)=1}}\sum_{|n^\prime|< 4N/d_1(d_2, d_2^\prime)}\min\bigg(\dfrac{M}{d_1[d_2, d_2^\prime]}+1, \dfrac{1}{\|n^\prime d_1^2d_2d_2^\prime\theta\|}\bigg).
 \end{align}
The terms with $n^\prime =0$ in \eqref{meth2i} contribute
 \begin{align}
\notag  &\leq D_1(\log X)^{h_1^2-1}\lVert {\alpha}_1\rVert_2^2\lVert {\alpha}_2 \rVert_2^2 \sum_{\substack{d_1\sim D_1}}\sum_{\substack{d_2, d_2^\prime \sim D_2\\(d_2d_2^\prime, d_1)=1}}\bigg(\dfrac{M}{d_1[d_2,d_2^\prime]} + 1\bigg)\\
\notag & \ll D_1M\lVert {\alpha}_1 \rVert_2^2\lVert {\alpha}_2\rVert_2^2(\log X)^{h_1^2+2} + (D_1D_2)^2\|\alpha_1\|_2^2 \|\alpha_2\|_2^2(\log X)^{h_1^2-1},
 \end{align}
using the fact that $\sum_{h_1, h_2\leq y}1/[h_1, h_2] \ll (\log y)^3$ for any $y\geq 2$. Therefore,
 \begin{align}
\notag \lvert \mathcal{S}_{\textup{Type II}}\rvert^2\ll &~\lVert {\alpha}_1\rVert_2^2\lVert {\alpha}_2 \rVert_2^2(\log X)^{h_1^2-1} \bigg\{MD_1(\log X)^{3} + D_1^2D_2^2\\
\label{meth2iii}  & + D_1\sum_{\substack{d_1\sim D_1}}\sum_{\substack{d_2, d_2^\prime \sim D_2\\(d_2d_2^\prime,d_1)=1}}\sum_{1\leq |n^\prime| < 4N/d_1(d_2, d_2^\prime)}\min\bigg(\dfrac{M}{d_1[d_2, d_2^\prime]} + 1, \dfrac{1}{\lVert n^\prime d_1^2d_2d_2^\prime\theta\rVert}\bigg)\bigg\}.
 \end{align}
 Next, we write $n^\prime d_2d_2^\prime =d''$, so that 
\[0<|d''|=|n^\prime| d_2d_2^\prime = |n^\prime| (d_2,d_2^\prime)[d_2, d_2^\prime] < \dfrac{4D_2^2N}{D_1},\] 
since $0<|n^\prime| < 4N/d_1(d_2, d_2^\prime)$ and $d_1\sim D_1$. Moreover,
\[\dfrac{M}{d_1[d_2, d_2^\prime]} = \dfrac{Md_1(d_2, d_2^\prime)|n^\prime|}{d_1^2 |n^\prime| d_2d_2^\prime} \ll  \dfrac{MN}{d_1^2|d''|}.\]
 The above reduction yields
 \begin{align}
\notag \lvert \mathcal{S}_{\textup{Type II}}\rvert^2\ll &~\|\alpha_1\|_2^2\|\alpha_2\|_2^2\bigg\{(D_1M+D_1^2D_2^2)(\log X)^{h_1^2+2}+ \\
\label{meth2ii} & + D_1(\log X)^{h_1^2-1}\sum_{d_1\sim D_1}\sum_{1\leq |d''|\ll D_2^2N/D_1}\uptau_3(d'')\min\bigg(\dfrac{MN}{d_1^2|d''|} + 1,\dfrac{1}{\lVert d_1^2d''\theta\rVert}\bigg)\bigg\}.
 \end{align}
We observe that if $D_2^2N/D_1\ll 1$, then we can bound the sum 
\[\sum_{d_1\sim D_1}\sum_{1\leq |d''|\ll D_2^2N/D_1}\uptau_3(d'')\min\bigg(\dfrac{MN}{d_1^2|d''|} + 1,\dfrac{1}{\lVert d_1^2d''\theta\rVert}\bigg) \ll \sum_{d_1\sim D_1}\bigg(\dfrac{MN}{d_1^2} + 1\bigg) \ll M + D_1. \]
Therefore, we can assume that $D_2^2N/D_1\gg1$, otherwise the sum over $d''$  in \eqref{meth2ii} can be bounded trivially as above. Without loss of generality, we can assume that $d''>0$ in the above sum.

Next, we apply Lemma \ref{Mikawa} with $\psi=1/4$ and recalling that $MN<X$ to obtain
\begin{align}
\notag D_1\sum_{d_1\sim D_1}&\sum_{0<d''\ll D_2^2N/D_1}\uptau_3(d'')\min\bigg(\dfrac{MN}{d_1^2d''} + 1,\dfrac{1}{\lVert d_1^2d''\theta\rVert}\bigg)\\
\notag \ll &~(\log X)\max_{1\leq J\leq D_2^2N/D_1}\bigg|D_1\sum_{d_1\sim D_1}\sum_{d''\sim J}\uptau_3(d'')\min\bigg(\dfrac{X}{d_1^2d''} + 1,\dfrac{1}{\lVert d_1^2d''\theta\rVert}\bigg)\bigg|\\
\notag \ll &~\bigg\{D_1D_2^2N + X\bigg(\dfrac{1}{D_1} + \dfrac{qH}{X} + \dfrac{1}{qH}\bigg)^{1/4}\bigg\}(\log X)^9.
\end{align}
Hence, from the above estimate together with \eqref{meth2ii}, and recalling from \eqref{lemmapeq2} that $\lVert {\alpha}_1\rVert_2\lVert {\alpha}_2 \rVert_2 \ll X^{1/2}(\log X)^{h^2+1}$, we obtain
\begin{align}
\notag \lvert \mathcal{S}_{\textup{Type II}}\rvert \ll &~ X^{1/2}\bigg(MD_1 + D_1^2D_2^2 + D_1D_2^2N+X\bigg(\dfrac{1}{D_1} + \dfrac{qH}{X} + \dfrac{1}{qH}\bigg)^{1/4}\bigg)^{1/2}\\
