\begin{align}
\sum_{d_1\leq D_1}\sideset{}{^*}\sum_{\substack{d_2\leq D_2}}\bigg\lvert \sum_{\substack{n< X\\n \equiv c \imod {d_1d_2}\\(n, b)=1}}\Lambda(n)e(n\theta)\bigg\rvert \ll_{b, \delta}  X\bigg(\dfrac{(qH)^{\delta/2}}{X^{\delta/2}} + \dfrac{1}{(qH)^{\delta/2}}\bigg)(\log X)^{C_2},
 \end{align}
 where $*$ in the sum denotes the conditions $(d_1, d_2)=(d_1d_2, bc)=1$.

\begin{align}
\sum_{d_1\leq D_1}\sideset{}{^*}\sum_{\substack{d_2\leq D_2}}\bigg\lvert \sum_{\substack{n< X\\n \equiv c \imod {d_1d_2}\\(n, b)=1}}\Lambda(n)e(n\theta)\bigg\rvert \ll_{b, \delta}  X\bigg(\dfrac{(qH)^{\delta/2}}{X^{\delta/2}} + \dfrac{1}{(qH)^{\delta/2}}\bigg)(\log X)^{C_2},
 \end{align}

We write
\begin{align}
\notag \sum_{d_1\leq D_1}\sideset{}{^*}\sum_{\substack{d_2\leq D_2}}\bigg\lvert \sum_{\substack{n< X\\n \equiv c \imod {d_1d_2}\\(n, b)=1}}\Lambda(n)e(n\theta)\bigg\rvert =\mathop{\sum\sum}_{\substack{d_1\leq D_1\\d_2\leq D_2}}\lambda(d_1, d_2)\sum_{\substack{n< X\\n \equiv c \imod {d_1d_2}\\(n, b)=1}}\Lambda(n)e(n\theta),
\end{align}
where $\lambda(d_1, d_2)$ is a complex number of absolute value $1$ whenever $( d_1d_2, bc)= (d_1, d_2)=1$ with $d_1\in [1, D_1]$ and $d_2\in [1, D_2]$. We now apply Proposition \ref{ExpGen} with \[{\sigma}(d)=\sum_{\substack{d_1d_2=d\\d_j\leq D_j\forall j}}\lambda(d_1, d_2),\] 
to establish the proposition. Note that $|{\sigma}| \leq \uptau$ in this case. So, it is enough to estimate the Type I and Type II sums. 

We can use Lemma \ref{lemmatype1} to estimate the Type I sums, which is similar to the proof of Proposition \ref{PropminorPrimeI}, so that condition \ref{TypeI} holds in Proposition \ref{ExpGen}. 

For Type II sums, we need to estimate the following sum
\begin{align}
\notag \Sigma_{\text{Type II}}:=\max_{\substack{D_1', D_2', M, N}}\mathop{\sum\sum}_{\substack{d_1\sim D_1'\\d_2\sim D_2'\\(d_1d_2, bc)=1\\(d_1,d_2)=1}}\bigg\lvert\sum_{\substack{mn<X\\mn\equiv c\imod {d_1d_2}\\m\sim M, n\sim N}}{\alpha}_1(m){\alpha}_2(n)e(mn\theta)\bigg\rvert,
\end{align}
where $|{\alpha}_1|, |{\alpha}_2|\leq \uptau_2 \cdot \log$ and the maximum is taken over those $D_1', D_2', M, N$ that satisfy
\begin{equation}\label{prop2eq1}
D_1'\in [1, D_1], \quad D_2'\in [1, D_2], \quad M, N\leq X^{2/3}, \quad  MN<X, \quad \text{and} \quad N\leq M.
\end{equation}

 We divide our analysis of the above Type II sum into two cases:

\noindent{\it Case 1:} Suppose that $M\leq X^{1/2}$. Then we write $d=d_1d_2$ so that $d_1d_2\in [D_1'D_2', 4D_1'D_2']$. We can now apply Corollary \ref{Cor: D} with $h=2$ and $h_1=2$ to obtain
\begin{align}\notag 
\Sigma_{\textup{Type II}} &\ll \max_{\substack{M, N\\ D\leq D_1D_2}}\sum_{\substack{d\sim D\\(d, bc)=1}}\uptau(d)\bigg\lvert\sum_{\substack{mn<X\\mn\equiv c\imod {d}\\m\sim M, n\sim N}}{\alpha}_1(m){\alpha}_2(n)e(mn\theta)\bigg\rvert\\
\notag &\ll \max_{\substack{M, N\\D\leq D_1D_2}}X\bigg(\dfrac{DM}{X} + \dfrac{D^2}{X} + \dfrac{M^{1/9}}{X^{1/9}} + \dfrac{(qH)^{1/9}}{X^{1/9}} + \dfrac{1}{(qH)^{1/9}}\bigg)^{1/2}(\log X)^{11}.
\end{align}
Note that by assumption $D_1\leq X^{1/3-\delta}$ and $D_2\leq X^{1/9}$. This implies that $D_1D_2\leq X^{4/9-\delta} \leq X^{1/2-\delta}$. Therefore,
\begin{align}\notag 
\Sigma_{\textup{Type II}}  &\ll X\bigg(\dfrac{(qH)^{\delta/2}}{X^{\delta/2}} + \dfrac{1}{(qH)^{\delta/2}}\bigg)(\log X)^{11}
\end{align}
by Remark \ref{Delta Remark}.


\noindent{\it Case 2:} Now we consider the case $M\geq X^{1/2}$. In this case, we have $N\leq X^{1/2}$. So,  applying Corollary \ref{Cor: D_1D_2ii} (b) with $h=2$, we obtain
\begin{align}\notag 
\Sigma_{\textup{Type II}} \ll &\max_{\substack{D_1', D_2', M, N}} X\bigg(\dfrac{D_1'M}{X} + \dfrac{(D_1'D_2')^2}{X} + \dfrac{D_1'(D_2')^{3/2}}{X^{1/2}} + \dfrac{M^{1/9}}{X^{1/9}} + \dfrac{(D_2'M)^{1/5}}{X^{1/5}} + \dfrac{(qH)^{1/9}}{X^{1/9}}\\
\notag &+ \dfrac{1}{(qH)^{1/9}}\bigg)^{1/2}(\log X)^{11}.
 \end{align}
Recall the relation \eqref{prop2eq1}, and note by assumption that $D_1\leq X^{1/3-\delta}$, and $D_2\leq X^{1/9}$, so that $D_1D_2\leq X^{4/9-\delta}$ and $D_1D_2^{3/2}\leq X^{1/2-\delta}$. Therefore, by Remark \ref{Delta Remark}, we have
\begin{align}
\notag \Sigma_{\textup{Type II}}&\ll X\bigg(\dfrac{(qH)^{\delta/2}}{X^{\delta/2}} + \dfrac{1}{(qH)^{\delta/2}}\bigg)(\log X)^{11}.
\end{align} 

The above two cases complete our analysis of Type II sum estimates. Hence, this completes the proof of the proposition.

