\label{expsemi}
Let $\varepsilon>0$ be small and let $\delta\in (0, 10^{-3}]$. Let $b$ be a fixed positive integer. Let $\lambda_{\textup{sem}}^-$ be a lower bound semi-linear sieve weights of level $D\in [2, X^{\frac{3}{7}(1-4\delta)-\varepsilon}]$, as given in Lemma \ref{fundsemi} and Lemma \ref{wellfacsem}. Let $\theta= a/q + \beta$ with $(a, q)=1$ and $\lvert \beta\rvert <1/q^2$. Furthermore, let $H=1+|\beta|X$ and $qH\in [1, X]$. Then, for some constant $C_4>0$, we have 
\begin{equation}\label{expsemieqM}
\sum_{\substack{d\leq D\\(d,2b)=1}}\lambda_{\textup{sem}}^-(d)\sum_{\substack{n<X\\n \equiv 1 \imod d\\ n\equiv 3\imod 8\\(n, b)=1}}\Lambda(n)e(n\theta)\ll_{b, \delta, \varepsilon}  X\bigg(\dfrac{(qH)^{\delta/2}}{X^{\delta/2}} + \dfrac{1}{(qH)^{\delta/2}}\bigg)(\log X)^{C_4}.
\end{equation}

\begin{equation}\label{expsemieqM}
\sum_{\substack{d\leq D\\(d,2b)=1}}\lambda_{\textup{sem}}^-(d)\sum_{\substack{n<X\\n \equiv 1 \imod d\\ n\equiv 3\imod 8\\(n, b)=1}}\Lambda(n)e(n\theta)\ll_{b, \delta, \varepsilon}  X\bigg(\dfrac{(qH)^{\delta/2}}{X^{\delta/2}} + \dfrac{1}{(qH)^{\delta/2}}\bigg)(\log X)^{C_4}.
\end{equation}

If $D\leq X^{1/10}$, the estimate in \eqref{expsemieqM} follows from Proposition \ref{PropminorPrimeI}. So, we may assume throughout the proof that $D\geq X^{1/10}$.

We now apply Proposition \ref{ExpGen} with ${\sigma}=\lambda_{\textup{sem}}^-$. In order to do that, we consider the following Type I and Type II sums:
\begin{align}
\notag \Sigma_{\textup{sem, Type I}}&:= \sum_{\substack{d\leq D\\(d, 2b)=1}}\lambda_{\textup{sem}}^-(d)\sum_{\substack{mn<X\\mn \equiv 1 \imod d\\mn\equiv 3\imod 8\\m\in [1, X^{1/3}]}}{\alpha}(m)\log^j(n)e(mn\theta),\\
\notag \Sigma_{\textup{sem, Type II}}&:= \max_{D', M, N}\bigg|\sum_{\substack{d\sim D'\\(d, 2b)=1}}\lambda_{\textup{sem}}^-(d)\sum_{\substack{mn<X\\mn \equiv 1 \imod d\\mn\equiv 3\imod 8\\m \sim M, n\sim N}}{\alpha}_1(m){\alpha}_2(n)e(mn\theta)\bigg|,
\end{align}
where $j\in \{0, 1\}$, $|{\alpha}|, |{\alpha}_1|, |{\alpha}_2|\leq \uptau_2\cdot \log$ and the maximum is over those $D', M, N$ that satisfy
\begin{equation}\label{semieq0}
D' \in [X^{1/10}, X^{\frac{3}{7}(1-4\delta)-\varepsilon}], \quad M, N\leq X^{2/3}, \quad N\leq M, \quad MN<X.
\end{equation}

First, we use Lemma \ref{lemmatype1} to estimate the type I sum with $h_1=2, h_2=1, h_3=1, M\leq X^{1/3}$ and $D\leq X^{3(1-4\delta)/7-\varepsilon}$ to obtain
\begin{align}
\notag \Sigma_{\textup{sem, Type I}} \ll X\bigg(\dfrac{(qH)^{\delta}}{X^{\delta}} + \dfrac{1}{(qH)^\delta}\bigg)(\log X)^6.
\end{align}
This implies that condition \ref{TypeI} holds in Proposition \ref{ExpGen}.

Next, by orthogonality of the Dirichlet characters $\chi_8$ modulo $8$, we have
\begin{align}
\notag |\Sigma_{\textup{sem, Type II}}|\leq \max_{D', M, N}\bigg|\sum_{\substack{d\sim D'\\(d, 2b)=1}}\lambda_{\textup{sem}}^-(d)\sum_{\substack{mn<X\\mn \equiv c \imod d\\m\sim M, n\sim N}}{\alpha}_1(m)\chi_8(m){\alpha}_2(n)\chi_8(n)e(mn\theta)\bigg|.
\end{align}


Next, we divide our analysis of the sum $\Sigma_{ \textup{sem, Type II}}$ into two cases. 

\noindent{\it Case 1:} Suppose that $M\leq X^{1/2}$. In this case, we use Corollary \ref{Cor: D} with $D=D'$, $c=1$, $h=2$, $h_1=1$, and the facts that $|\lambda_{\textup{sem}}^-|\leq 1$ and $D'\leq X^{3/7} \leq X^{1/2-2\delta}$, to obtain

\begin{align}\notag 
\Sigma_{ \textup{sem, Type II}}  & \ll  X\bigg(\dfrac{(qH)^\delta}{X^\delta} + \dfrac{1}{(qH)^\delta}\bigg)(\log X)^{10}.
\end{align}


\paragraph{\it Case 2:} Suppose that $M\in [X^{1/2}, X^{2/3}]$. The assumption on $M$ implies that $N\leq X^{1/2}$. We now consider two subcases.

\noindent{\it Case 2(a):} Suppose that $D' \in [X^{1/10}, X^{3(1-4\delta)/7-\varepsilon}]$ and $D' \leq X^{1-2\delta-\varepsilon^2}/M$. Recalling that $|\lambda_{\textup{sem}}^-|\leq 1$, and by Corollary \ref{Cor: D} with $D=D'$, $c=1$, $h=2$, $h_1=1$,  we obtain
\begin{align}
\notag \Sigma_{ \textup{sem, Type II}} & \ll \max_{D', M, N}X\bigg(\dfrac{D'M}{X}+ \dfrac{(D')^2}{X} +\dfrac{M^{1/9}}{X^{1/9}} + \dfrac{(qH)^{1/9}}{X^{1/9}} + \dfrac{1}{(qH)^{1/9}}\bigg)^{1/2}(\log X)^{10}.
\end{align}
By assumption, $D'M/X \leq X^{-2\delta-\varepsilon^2} \leq  X^{-2\delta}$, $D'\leq X^{3/7} \leq X^{1/2-2\delta}$, and $M\leq X^{2/3}$, so by Remark \ref{Delta Remark} we have
\begin{align}
 \notag \Sigma_{ \textup{sem, Type II}} &\ll  X\bigg(\dfrac{(qH)^\delta}{X^\delta} + \dfrac{1}{(qH)^\delta}\bigg)(\log X)^{10}.
\end{align}

\paragraph{\it Case 2(b):} Finally, we consider the case when $D' \in [X^{1/10}, X^{3(1-4\delta)/7-\varepsilon}]$ and $D' >X^{1-2\delta-\varepsilon^2}/M$. 

Note that the sifting parameter associated with $\lambda_{\textup{sem}}^-$ is $\leq X^{1/3-2\delta-2\varepsilon^2}$. We fix a parameter $D_0 \in [X^{1/3-2\delta-2\varepsilon^2}, X^{3(1-4\delta)/7-\varepsilon}]$ to be chosen shortly. Then any $d\sim D'$ in the support of $\lambda_{\textup{sem}}^-$ can be written as $d=d_1d_2$ with $d_1\in [X^{1/10}, D_0]$ and $d_1d_2^2\leq X^{1-4\delta-2\varepsilon^2}/D_0$. 

We take $D_0=X^{1-2\delta-\varepsilon^2}/M$. Note that since $M\in [X^{1/2}, X^{2/3}]$, this implies that $D_0\geq X^{1/3-2\delta-\varepsilon^2}$ and by assumption, $D_0=X^{1-2\delta-\varepsilon^2}/M < D'\leq X^{3(1-4\delta)/7 -\varepsilon}$, so Lemma \ref{wellfacsem} is applicable in this case. Next, we perform a dyadic decomposition of the range of the variables $d_1$ and $d_2$, so that
\begin{align}
\notag &d_1\sim D_1,\: d_2\sim D_2, \quad \text{where}\quad X^{1/10} \ll D_1\leq D_0, \: \quad D_1D_2^2 \leq \dfrac{X^{1-4\delta-2\varepsilon^2}}{D_0}, \quad D_1D_2\asymp D'.
 \end{align}
